@tool
extends Node

func run() -> String:
	var d := DirAccess.open("res://")
	if not d.dir_exists("probe_del/nested"):
		var mk := d.make_dir_recursive("probe_del/nested")
		if mk != OK:
			return "S12a mkdir rc=" + str(mk)
	var f := FileAccess.open("res://probe_del/nested/a.txt", FileAccess.WRITE)
	if f == null:
		return "S12a file null"
	f.store_string("x")
	f.close()
	return "S12a ok exists=" + str(FileAccess.file_exists("res://probe_del/nested/a.txt"))
